"""
Script to validate spatial clustering proxies for all datasets and
write a consolidated validation report to
data/manifests/spatial_proxy_validation.json.

This script addresses the failure in the previous implementation where
non‑numeric columns caused a `ValueError` when converting the raw data
to `float`. The updated logic:

* Loads the proxy report generated by `generate_spatial_proxy.py`.
* Reads each raw dataset (CSV or Excel) using pandas.
* Converts the dataset to a numeric matrix, coercing non‑numeric values
  to `NaN` and then filling them with zeros (a neutral placeholder for
  silhouette computation).
* If a proxy was not generated (or missing labels), it regenerates the
  proxy on the numeric data.
* Calls `validate_spatial_proxy` from `dependency_injector.py`, which
  computes the silhouette score and checks the proxy against the
  FR‑003 feature‑space validation criteria.
* Writes a consolidated JSON validation report to
  `data/manifests/spatial_proxy_validation.json`.

The script is executed via the task runner (`python code/validate_spatial_proxy.py`)
and logs progress using the project's logging utilities.
"""

import json
from pathlib import Path
from typing import Any, Dict

import pandas as pd
import numpy as np

from llmxive_toolkit import paths, get_logger
from dependency_injector import (
    generate_spatial_proxy,
    validate_spatial_proxy,
)

log = get_logger(__name__)


def _load_numeric_data(csv_path: Path) -> np.ndarray:
    """
    Load a dataset and return a numeric NumPy array.

    Non‑numeric columns are coerced to NaN and then filled with zeros.
    This ensures the silhouette computation receives a purely numeric
    matrix without raising conversion errors.
    """
    # Try CSV first; fallback to Excel if needed
    if csv_path.suffix.lower() == ".csv":
        df = pd.read_csv(csv_path, header=None)
    else:
        df = pd.read_excel(csv_path, header=None)

    # Coerce everything to numeric, turning strings into NaN
    df_numeric = df.apply(pd.to_numeric, errors="coerce")

    # Fill NaN values with zero – a neutral value that does not affect
    # cluster shape dramatically for silhouette computation.
    df_filled = df_numeric.fillna(0)

    return df_filled.values.astype(float)


def main() -> None:
    # Load the existing proxy report (generated by generate_spatial_proxy.py)
    proxy_report_path = paths.data("manifests", "spatial_proxy_report.json")
    if not proxy_report_path.is_file():
        log.error(f"Proxy report not found at {proxy_report_path}")
        raise FileNotFoundError(f"Proxy report not found at {proxy_report_path}")

    with open(proxy_report_path, "r") as f:
        proxy_report: Dict[str, Any] = json.load(f)

    validation_results: Dict[str, Any] = {}

    for dataset_name, proxy_data in proxy_report.items():
        # Determine raw dataset location (CSV preferred, then XLS)
        raw_path_csv = paths.data("raw", f"{dataset_name}.csv")
        raw_path_xls = paths.data("raw", f"{dataset_name}.xls")

        if raw_path_csv.is_file():
            raw_path = raw_path_csv
        elif raw_path_xls.is_file():
            raw_path = raw_path_xls
        else:
            log.warning(f"Raw data file for dataset '{dataset_name}' not found; skipping.")
            continue

        try:
            data_array = _load_numeric_data(raw_path)
        except Exception as e:
            log.error(f"Failed to load numeric data for dataset '{dataset_name}': {e}")
            continue

        # If the proxy report is empty or missing labels, regenerate it
        if not proxy_data or not proxy_data.get("labels"):
            log.info(f"Generating spatial proxy for dataset '{dataset_name}' on the fly.")
            proxy_data = generate_spatial_proxy(data_array, n_clusters=3)

        # Perform validation using the FR‑003 logic
        result = validate_spatial_proxy(data_array, proxy_data, threshold=0.25)
        validation_results[dataset_name] = result

    # Write consolidated validation report
    validation_path = paths.data("manifests", "spatial_proxy_validation.json")
    with open(validation_path, "w") as f:
        json.dump(validation_results, f, indent=2)

    log.info(f"Spatial proxy validation report written to {validation_path}")


if __name__ == "__main__":
    main()